//! Checks detection's first object-level filter against QuPath's own output.
//!
//! Fixture generated by `parity/java/ObjectFilters.java` via
//! `./parity/record.sh`, recorded through the loop that measures each traced
//! ROI on `ipToMeasure` and keeps or drops it. Needs no slide.
//!
//! Both halves are checked against the recorded values: the statistics QuPath
//! computed for each region, and the decision it took. Checking only the
//! decision would pass a mean that is wrong by less than the distance to the
//! threshold, which is most wrong means.
//!
//! **Means are compared bit for bit, not within a tolerance.** Nothing here is
//! transcendental — it is a sum of `f32` values widened to `f64` and divided by
//! a count — so the only way to differ is to accumulate in a different order or
//! a different width, and both are defects rather than drift. §5's `1e-5` exists
//! for `exp` and `sqrt`, not for addition.

use qupath_pipeline::ObjectFilter;
use qupath_watershed::RegionTracer;

fn fixture() -> std::path::PathBuf {
    std::path::Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("../../parity/fixtures/ObjectFilters.json")
}

/// Extracts the text between two markers, starting the search at `from`.
fn between<'a>(haystack: &'a str, start: &str, end: &str, from: usize) -> (&'a str, usize) {
    let open = haystack[from..].find(start).expect(start) + from + start.len();
    let close = haystack[open..].find(end).expect(end) + open;
    (&haystack[open..close], close)
}

fn ints(text: &str) -> Vec<u32> {
    if text.trim().is_empty() {
        return Vec::new();
    }
    text.split(',')
        .map(|v| v.trim().parse().expect("integer"))
        .collect()
}

fn floats(text: &str) -> Vec<f32> {
    if text.trim().is_empty() {
        return Vec::new();
    }
    text.split(',')
        .map(|v| v.trim().parse().expect("float"))
        .collect()
}

/// Java prints `NaN` and `Infinity`, both of which Rust parses.
fn doubles(text: &str) -> Vec<f64> {
    if text.trim().is_empty() {
        return Vec::new();
    }
    text.split(',')
        .map(|v| v.trim().parse().expect("double"))
        .collect()
}

fn scalar(text: &str, key: &str, from: usize) -> (f64, usize) {
    let (value, at) = between(text, &format!("\"{key}\": "), ",", from);
    (value.trim().parse().expect(key), at)
}

#[expect(
    clippy::cast_possible_truncation,
    clippy::cast_sign_loss,
    reason = "recorded dimensions and counts are small positive integers"
)]
fn index(value: f64) -> usize {
    value as usize
}

#[test]
fn matches_qupath_object_filters() {
    let path = fixture();
    let text = std::fs::read_to_string(&path)
        .unwrap_or_else(|e| panic!("{}: {e}; run ./parity/record.sh", path.display()));
    let (cases, _) = between(&text, "\"cases\": [", "\n  ]\n}", 0);

    let mut count = 0usize;
    let (mut regions_seen, mut kept_seen) = (0u32, 0u32);
    let mut at = 0usize;
    // One tracer and one filter across every case: buffers left dirty by a
    // previous case would show up here and nowhere else.
    let mut tracer = RegionTracer::new();
    let mut filter = ObjectFilter::new();
    while let Some(start) = cases[at..].find("{\"name\": \"") {
        let from = at + start;
        let (name, next) = between(cases, "\"name\": \"", "\"", from);
        let (width, next) = scalar(cases, "width", next);
        let (height, next) = scalar(cases, "height", next);
        let (threshold, next) = scalar(cases, "threshold", next);
        let (expected_regions, next) = scalar(cases, "roiCount", next);
        let (_, next) = scalar(cases, "overlaps", next);
        let (has_mask, next) = scalar(cases, "hasBackgroundMask", next);
        let (labels_text, next) = between(cases, "\"labels\": [", "]", next);
        let (measure_text, next) = between(cases, "\"toMeasure\": [", "]", next);
        let (mask_text, next) = between(cases, "\"backgroundMask\": [", "]", next);
        let (_, next) = between(cases, "\"regions\": [", "]", next);
        let (areas_text, next) = between(cases, "\"areas\": [", "]", next);
        let (means_text, next) = between(cases, "\"means\": [", "]", next);
        let (kept_text, next) = between(cases, "\"kept\": [", "]", next);
        let (binary_text, next) = between(cases, "\"binary\": [", "]", next);
        at = next;

        let (width, height) = (index(width), index(height));
        let labels: Vec<f32> = ints(labels_text).into_iter().map(|v| v as f32).collect();
        let to_measure = floats(measure_text);
        let mask: Vec<f32> = ints(mask_text).into_iter().map(|v| v as f32).collect();
        let their_areas = ints(areas_text);
        let their_means = doubles(means_text);
        let their_kept: Vec<bool> = ints(kept_text).into_iter().map(|v| v != 0).collect();
        let their_binary = floats(binary_text);

        assert_eq!(to_measure.len(), width * height, "{name}: measured image");
        assert_eq!(
            mask.is_empty(),
            index(has_mask) == 0,
            "{name}: the recorded mask disagrees with the recorded flag"
        );

        let mut regions = vec![0u32; labels.len()];
        let found = tracer.trace_into(&labels, &mut regions, width, 0.5, f32::INFINITY);
        assert_eq!(u64::from(found), index(expected_regions) as u64, "{name}");

        let background = if mask.is_empty() {
            None
        } else {
            Some(mask.as_slice())
        };
        let kept = filter.apply(&to_measure, &regions, found, threshold, background);

        for (region, (&theirs, ours)) in their_areas.iter().zip(filter.stats()).enumerate() {
            assert_eq!(
                ours.area,
                theirs,
                "{name}: region {} covers {} countable pixels, QuPath counts {theirs}",
                region + 1,
                ours.area
            );
        }
        for (region, (&theirs, ours)) in their_means.iter().zip(filter.stats()).enumerate() {
            assert_eq!(
                ours.mean.to_bits(),
                theirs.to_bits(),
                "{name}: region {} has mean {}, QuPath has {theirs}",
                region + 1,
                ours.mean
            );
        }
        assert_eq!(
            filter.kept(),
            their_kept.as_slice(),
            "{name}: a different set of regions survived"
        );

        let mut binary = vec![0.0f32; labels.len()];
        filter.write_binary(&regions, &mut binary);
        for (at, (&ours, &theirs)) in binary.iter().zip(&their_binary).enumerate() {
            assert_eq!(
                ours,
                theirs,
                "{name}: at {at} ({}, {}) our binary is {ours}, QuPath's is {theirs}",
                at % width,
                at / width
            );
        }

        println!("{name:>26}  {found:>4} regions  {kept:>4} kept");
        regions_seen += found;
        kept_seen += kept;
        count += 1;
    }

    assert!(count >= 17, "only {count} cases in the fixture");

    for (name, why) in [
        (
            "mean-exactly-threshold",
            "the mean test is `<=`, so landing on the threshold is out",
        ),
        (
            "non-finite-pixels",
            "statistics skip NaN and infinities, in pixelCount as well as the sum",
        ),
        (
            "background-mask-hit",
            "one masked pixel rejects the whole region",
        ),
        (
            "background-mask-miss",
            "a mask that exists but misses rejects nothing",
        ),
        (
            "ring-with-hole",
            "the filled hole is measured, and here it is what drops the object",
        ),
        (
            "log-chain",
            "the survival rate on the input this stage meets in the pipeline",
        ),
    ] {
        assert!(cases.contains(name), "{name} missing: {why} is unchecked");
    }

    println!("{count} images  {regions_seen} regions  {kept_seen} kept, all matching");
}
